package io.github.diodeme.ji.host;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.session.model.CanonicalSessionState;
import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import org.junit.jupiter.api.Test;

final class SessionRetentionPolicyTest {
    private static final Instant NOW = Instant.parse("2026-09-06T00:00:00Z");

    @Test
    void trashRestoreAndPermanentDeletionUseRevisionCasAndThirtyDayBoundary() {
        var policy = SessionRetentionPolicy.defaults();
        var available = state(CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 5);
        SessionRetentionPolicy.Record trashed = policy.trash(available, 5, NOW);

        assertEquals(CanonicalSessionState.SessionStatus.TRASHED, trashed.state().status());
        assertThrows(SessionRetentionException.class,
                () -> policy.permanentlyDelete(trashed, trashed.state().revision(), NOW.plus(Duration.ofDays(29))));
        SessionRetentionPolicy.Record restored = policy.restore(trashed, trashed.state().revision(), NOW.plusSeconds(1));
        assertEquals(CanonicalSessionState.SessionStatus.AVAILABLE, restored.state().status());

        SessionRetentionPolicy.Record expired = policy.trash(restored.state(), restored.state().revision(), NOW);
        SessionRetentionPolicy.Tombstone tombstone = policy.permanentlyDelete(
                expired, expired.state().revision(), NOW.plus(Duration.ofDays(30)));
        assertEquals("session-1", tombstone.sessionId());
        assertEquals(CanonicalSessionState.SessionOutcome.DELETED, tombstone.outcome());
        assertEquals(NOW.plus(Duration.ofDays(30)), tombstone.deletedAt());
    }

    @Test
    void tombstoneContainsNoRecoverableContentAndCannotBeResurrected() {
        var policy = new SessionRetentionPolicy(Duration.ZERO);
        var trashed = policy.trash(state(CanonicalSessionState.SessionStatus.AVAILABLE, Optional.empty(), 0), 0, NOW);
        SessionRetentionPolicy.Tombstone tombstone = policy.permanentlyDelete(
                trashed, trashed.state().revision(), NOW);

        assertEquals("session-1", tombstone.sessionId());
        assertThrows(SessionRetentionException.class, () -> policy.assertCreatable("session-1", Optional.of(tombstone)));
    }

    private static CanonicalSessionState state(
            CanonicalSessionState.SessionStatus status,
            Optional<CanonicalSessionState.SessionOutcome> outcome,
            long revision) {
        return new CanonicalSessionState(new CanonicalSessionState.SessionId("session-1"), status, outcome,
                revision, Optional.empty(), java.util.List.of(), java.util.List.of());
    }
}
